function appendMapPage(host,c){
 const kids=childPoints(c),pad=52,focusedFragment=fragments.find(f=>f.focus===c.id);
 const minX=Math.min(c.x-145,...kids.map(p=>p.x-125),...(focusedFragment?[focusedFragment.x-90]:[])),maxX=Math.max(c.x+145,...kids.map(p=>p.x+125),...(focusedFragment?[focusedFragment.x+90]:[]));
 const minY=Math.min(c.y-105,...kids.map(p=>p.y-72),...(focusedFragment?[focusedFragment.y-70]:[])),maxY=Math.max(c.y+105,...kids.map(p=>p.y+72),...(focusedFragment?[focusedFragment.y+70]:[]));
 const mapW=maxX-minX+pad*2,mapH=maxY-minY+pad*2;
 const pageWidth=Math.max(1200,mapW+90),page=document.createElement("section");
 page.style.cssText=`width:${pageWidth}px;padding:34px 38px 28px;background:#f4eee4;color:#272c33;`;
 const map=document.createElement("div");map.className="stage";map.style.cssText=`position:relative;width:${mapW}px;height:${mapH}px;margin:0 auto;transform:none;background:radial-gradient(circle at center,rgba(255,255,255,.42),transparent 54%),linear-gradient(rgba(25,59,98,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(25,59,98,.03) 1px,transparent 1px);background-size:auto,32px 32px,32px 32px;contain:none;`;
 const svgCopy=document.createElementNS("http://www.w3.org/2000/svg","svg");svgCopy.setAttribute("viewBox",`${minX-pad} ${minY-pad} ${mapW} ${mapH}`);svgCopy.style.cssText=`position:absolute;inset:0;width:${mapW}px;height:${mapH}px;overflow:visible;z-index:1;`;
 kids.forEach((point,i)=>{const path=document.createElementNS("http://www.w3.org/2000/svg","path");path.setAttribute("d",curve({x:c.x,y:c.y},point,(i-1)*.04));path.setAttribute("fill","none");path.setAttribute("stroke","rgba(25,59,98,.68)");path.setAttribute("stroke-width","3");svgCopy.appendChild(path)});map.appendChild(svgCopy);
 const originalNode=document.querySelector(`.concept[data-id="${c.id}"]`),node=originalNode.cloneNode(true);node.classList.remove("dimmed");node.classList.add("active");node.style.left=`${c.x-minX+pad}px`;node.style.top=`${c.y-minY+pad}px`;node.style.transition="none";map.appendChild(node);
 c.children.forEach((ch,i)=>{const el=document.createElement("div");el.className="child show";el.style.left=`${kids[i].x-minX+pad}px`;el.style.top=`${kids[i].y-minY+pad}px`;el.innerHTML=`<strong>${ch[0]}</strong><small>${ch[1]}</small>`;map.appendChild(el)});
 if(focusedFragment){const fnode=document.querySelector(`.fragment[data-frag="${focusedFragment.id}"]`).cloneNode(true);fnode.style.left=`${focusedFragment.x-minX+pad}px`;fnode.style.top=`${focusedFragment.y-minY+pad}px`;fnode.style.opacity="1";map.appendChild(fnode)}
 page.appendChild(map);
 const details=document.createElement("div");details.style.cssText=`display:grid;grid-template-columns:${IMAGES[c.image]?"1fr 180px":"1fr"};gap:22px;margin:18px auto 0;padding:19px 22px;background:#fffaf2;border:1px solid rgba(25,59,98,.15);border-radius:18px;max-width:1200px;`;
 const copy=document.createElement("div"),heading=document.createElement("h2"),description=document.createElement("p"),short=document.createElement("p");
 heading.textContent=c.title;heading.style.cssText="margin:0 0 7px;color:#193b62;font:700 26px Georgia,serif";
 short.textContent=c.short;short.style.cssText="margin:0 0 9px;color:#70737a;font-size:15px;font-weight:600";
 description.textContent=c.text;description.style.cssText="margin:0;color:#454a51;font-size:15px;line-height:1.5";
 copy.append(heading,short,description);
 details.appendChild(copy);
 if(IMAGES[c.image]){const image=document.createElement("img");image.src=IMAGES[c.image];image.alt=`Imagem relacionada a ${c.title}`;image.style.cssText="width:180px;height:150px;object-fit:cover;border-radius:14px;align-self:center;background:#eee6da";details.appendChild(image)}
 page.appendChild(details);host.appendChild(page);
}
async function buildPdf(){
 if(!window.jspdf?.jsPDF)throw new Error("A biblioteca de PDF não carregou. Verifique a conexão e tente novamente.");
 const paper=document.getElementById("pdfPaper").value,jsPDF=window.jspdf.jsPDF;
 const pdf=new jsPDF({orientation:"landscape",unit:"mm",format:paper,compress:true});
 const pageW=pdf.internal.pageSize.getWidth(),pageH=pdf.internal.pageSize.getHeight(),margin=10;
 const coverHost=makeExportHost(1200);appendCoverPage(coverHost);
 let canvas;
 try{
  canvas=await exportCanvas(coverHost);const coverData=canvas.toDataURL("image/jpeg",.96),coverScale=Math.min((pageW-margin*2)/canvas.width,(pageH-margin*2)/canvas.height),coverW=canvas.width*coverScale,coverH=canvas.height*coverScale;
  pdf.addImage(coverData,"JPEG",(pageW-coverW)/2,(pageH-coverH)/2,coverW,coverH,undefined,"FAST");
 }finally{coverHost.remove();if(canvas){canvas.width=canvas.height=1;canvas=null}}
 pdf.addPage(paper,"landscape");
 const original=stage.cloneNode(true);original.querySelectorAll(".child").forEach(el=>el.remove());original.querySelectorAll(".link.sub").forEach(el=>el.remove());
 original.querySelectorAll(".concept,.fragment").forEach(el=>el.classList.remove("active","dimmed"));
 original.querySelectorAll(".link").forEach(el=>{el.style.animation="none";el.style.strokeDasharray="none"});
 const allX=[root.x-175,...concepts.map(c=>c.x-150),...fragments.map(f=>f.x-90)],allRight=[root.x+175,...concepts.map(c=>c.x+150),...fragments.map(f=>f.x+90)];
 const allY=[root.y-120,...concepts.map(c=>c.y-100),...fragments.map(f=>f.y-70)],allBottom=[root.y+120,...concepts.map(c=>c.y+100),...fragments.map(f=>f.y+70)];
 const minX=Math.min(...allX)-70,minY=Math.min(...allY)-70,width=Math.max(...allRight)-minX+70,height=Math.max(...allBottom)-minY+70;
 shiftStageClone(original,minX,minY,width,height);
 const overview=makeExportHost(width);overview.style.width=`${width}px`;overview.style.height=`${height}px`;overview.appendChild(original);
 pdfStatus.textContent="Preparando visão geral…";
 try{
  canvas=await exportCanvas(overview);const data=canvas.toDataURL("image/jpeg",.94),scale=Math.min((pageW-margin*2)/canvas.width,(pageH-margin*2)/canvas.height),drawW=canvas.width*scale,drawH=canvas.height*scale;
  pdf.addImage(data,"JPEG",(pageW-drawW)/2,(pageH-drawH)/2,drawW,drawH,undefined,"FAST");
 }finally{overview.remove();if(canvas){canvas.width=canvas.height=1}}
 for(let i=0;i<concepts.length;i++){
  pdfStatus.textContent=`Preparando tópico ${i+1} de ${concepts.length}…`;
  const c=concepts[i],host=makeExportHost(1200);appendMapPage(host,c);
  try{
   canvas=await exportCanvas(host);const data=canvas.toDataURL("image/jpeg",.94);
   pdf.addPage(paper,"landscape");
   const scale=Math.min((pageW-margin*2)/canvas.width,(pageH-margin*2)/canvas.height),drawW=canvas.width*scale,drawH=canvas.height*scale;
   pdf.addImage(data,"JPEG",(pageW-drawW)/2,(pageH-drawH)/2,drawW,drawH,undefined,"FAST");
  }finally{host.remove();if(canvas){canvas.width=canvas.height=1;canvas=null}}
 }
 pdf.save("mapa-mental-paulo-freire.pdf");
}
generatePdfButton.addEventListener("click",async()=>{
 generatePdfButton.disabled=true;pdfStatus.textContent="Iniciando…";
 try{await buildPdf();pdfStatus.textContent="PDF baixado.";setTimeout(()=>pdfModal.hide(),700)}
 catch(error){console.error(error);pdfStatus.textContent=error.message||"Não foi possível gerar o PDF."}
 finally{generatePdfButton.disabled=false}
});

/* toque/arraste/pinch */
viewport.addEventListener("pointerdown",e=>{
 if(e.target.closest("button"))return;
 stopCameraAnimation();
 viewport.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(pointers.size===1){dragging=false;panStart={x:e.clientX,y:e.clientY,tx,ty};viewport.classList.add("dragging")}
 if(pointers.size===2){const a=[...pointers.values()];lastDist=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)}
});
viewport.addEventListener("pointermove",e=>{
 if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(pointers.size===1&&panStart){const dx=e.clientX-panStart.x,dy=e.clientY-panStart.y;if(Math.hypot(dx,dy)>4)dragging=true;tx=panStart.tx+dx;ty=panStart.ty+dy;queueApply()}
 else if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);if(lastDist){const cx=(a[0].x+a[1].x)/2-viewportRect.left,cy=(a[0].y+a[1].y)/2-viewportRect.top;zoomAt(d/lastDist,cx,cy)}lastDist=d}
});
function endP(e){pointers.delete(e.pointerId);if(pointers.size<2)lastDist=null;if(!pointers.size){viewport.classList.remove("dragging");panStart=null;setTimeout(()=>dragging=false,40)}}
viewport.addEventListener("pointerup",endP);viewport.addEventListener("pointercancel",endP);

/* principal: tocar outro nó troca de foco diretamente */
viewport.addEventListener("click",e=>{
 if(e.target===viewport && active){sheet.classList.remove("show")}
});

let resizeFrame=0;
new ResizeObserver(()=>{if(resizeFrame)return;resizeFrame=requestAnimationFrame(()=>{
 resizeFrame=0;viewportRect=viewport.getBoundingClientRect();applyResponsiveLayout();
 const focused=active&&concepts.find(c=>c.id===active);
 if(focused)centerAt(focused.x,focused.y,Math.max(baseScale(),mobileQuery.matches ? .74 : .9));
 else centerAt(root.x,root.y,baseScale());
})}).observe(viewport);
applyResponsiveLayout();setTrail(null);requestAnimationFrame(()=>centerAt(root.x,root.y,baseScale()));
setTimeout(()=>{tip.style.transition="opacity .25s";tip.style.opacity="0";setTimeout(()=>tip.hidden=true,260)},3200);
